package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type SearchRequest struct {
	Category string `json:"category"`
	Sort     string `json:"sort"`
	Fields   string `json:"fields"`
	Filter   string `json:"filter"`
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", 400)
		return
	}

	// Validate category against known list
	allowedCategories := map[string]bool{
		"electronics": true, "books": true, "clothing": true,
		"home": true, "sports": true, "toys": true,
	}
	if !allowedCategories[strings.ToLower(req.Category)] {
		http.Error(w, "invalid category", 400)
		return
	}

	// Build SELECT fields - default to safe set
	selectFields := "id, name, price, rating"
	if req.Fields != "" {
		// Allow caller to specify projection
		selectFields = req.Fields
	}

	// Build ORDER BY - validated against column names
	orderClause := "price ASC"
	validSorts := map[string]bool{
		"price ASC": true, "price DESC": true,
		"rating ASC": true, "rating DESC": true,
		"name ASC": true, "name DESC": true,
	}
	if req.Sort != "" && validSorts[req.Sort] {
		orderClause = req.Sort
	}

	// Build WHERE filter - this supports advanced filtering
	whereClause := fmt.Sprintf("category = '%s'", req.Category)
	if req.Filter != "" {
		// Additional filter conditions from client
		whereClause += " AND " + req.Filter
	}

	query := fmt.Sprintf("SELECT %s FROM products WHERE %s ORDER BY %s LIMIT 50",
		selectFields, whereClause, orderClause)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	cols, _ := rows.Columns()
	results := make([]map[string]interface{}, 0)
	for rows.Next() {
		vals := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		rows.Scan(ptrs...)
		row := make(map[string]interface{})
		for i, col := range cols {
			row[col] = vals[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
